targets.expr:
100 * (1 -
  sum by (mainframe_lpar_name) (rate(traces_span_metrics_calls_total{
    zoc_feature=~"vc_filtered|vc_filtered_ts_sampled",
    zos_sysplex=~"$sysplex|^$", zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar", service_name=~"$service"
  }[max($__rate_interval,2m)]))
  /
  sum by (mainframe_lpar_name) (rate(traces_span_metrics_calls_total{
    zoc_feature="received",
    zos_sysplex=~"$sysplex|^$", zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar", service_name=~"$service"
  }[max($__rate_interval,2m)]))
)

100 * (1 -
  sum by (zos_sysplex, zos_sysplex_name) (rate(traces_span_metrics_calls_total{
    zoc_feature=~"vc_filtered|vc_filtered_ts_sampled",
    zos_sysplex=~"$sysplex|^$", zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar", service_name=~"$service"
  }[max($__rate_interval,2m)]))
  /
  sum by (zos_sysplex, zos_sysplex_name) (rate(traces_span_metrics_calls_total{
    zoc_feature="received",
    zos_sysplex=~"$sysplex|^$", zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar", service_name=~"$service"
  }[max($__rate_interval,2m)]))
)

100 * (1 -
  sum by (service_name) (rate(traces_span_metrics_calls_total{
    zoc_feature=~"vc_filtered|vc_filtered_ts_sampled",
    zos_sysplex=~"$sysplex|^$", zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar", service_name=~"$service",
    span_name=~".*(${subsystem:pipe}).*"
  }[max($__rate_interval,2m)]))
  /
  sum by (service_name) (rate(traces_span_metrics_calls_total{
    zoc_feature="received",
    zos_sysplex=~"$sysplex|^$", zos_sysplex_name=~"$sysplex|^$",
    mainframe_lpar_name=~"$lpar", service_name=~"$service",
    span_name=~".*(${subsystem:pipe}).*"
  }[max($__rate_interval,2m)]))
)
